<?php
namespace Reseller\Security;

// Runtime class: loaded only through init.php (NUXR_RUNTIME); never executable on its own.
if (!defined('NUXR_RUNTIME')) { http_response_code(404); exit; }

/**
 * WP9-D / NEW-7 (owner decision O7-A): one dedicated application key, never the database password,
 * with purpose-separated subkeys for every signature the application makes.
 *
 * - $app_secret is a config.php value of at least 32 characters, generated by the installer and
 *   provisioned on upgrade (WP10 key provisioning). It must differ from $db_pass, $api_secret and
 *   $radius_rest_secret.
 * - There is NO fallback to the database password: without a valid key every signed feature fails
 *   closed (staff and customer sessions, remember cookies, login links, public invoice links, OTP).
 * - Subkeys: HMAC-SHA256(app_secret, "nuxr-subkey|v1|<purpose>"). A signature made for one purpose
 *   never verifies for another.
 */
final class AppKey
{
    public const MIN_LENGTH = 32;

    public const STAFF_SESSION = 'staff-session';
    public const STAFF_COOKIE = 'staff-cookie';
    public const CUSTOMER_COOKIE = 'customer-cookie';
    public const CUSTOMER_LINK = 'customer-link';
    public const VOUCHER_INVOICE = 'voucher-invoice';
    public const OTP_FILE = 'otp-file';

    /** The dedicated key, or null when every signed feature must fail closed. */
    public static function secret(): ?string
    {
        $s = $GLOBALS['app_secret'] ?? null;
        if (!is_string($s) || strlen($s) < self::MIN_LENGTH) {
            return null;
        }
        foreach (['db_pass', 'api_secret', 'radius_rest_secret', 'radius_pass'] as $other) {
            $o = $GLOBALS[$other] ?? null;
            if (is_string($o) && $o !== '' && hash_equals($o, $s)) {
                return null;
            }
        }
        return $s;
    }

    public static function available(): bool
    {
        return self::secret() !== null;
    }

    /** HMAC-SHA256 (hex) of $message under the subkey of $purpose, or null without a valid key. */
    public static function mac(string $purpose, string $message): ?string
    {
        $s = self::secret();
        if ($s === null) {
            return null;
        }
        $sub = hash_hmac('sha256', 'nuxr-subkey|v1|' . $purpose, $s, true);
        return hash_hmac('sha256', $message, $sub);
    }

    /** Constant-time verification; false without a valid key or for a malformed MAC. */
    public static function verify(string $purpose, string $message, mixed $mac): bool
    {
        if (!is_string($mac) || !preg_match('/^[0-9a-f]{64}$/', $mac)) {
            return false;
        }
        $want = self::mac($purpose, $message);
        return $want !== null && hash_equals($want, $mac);
    }

    /** Public voucher-invoice link signature (replaces md5(id . db_pass)). */
    public static function voucherInvoiceSignature(int|string $id): ?string
    {
        return self::mac(self::VOUCHER_INVOICE, 'id|' . (string) $id);
    }

    /** OTP file name stem for an identity (replaces sha1(identity . db_pass)); null without a key. */
    public static function otpName(string $identity): ?string
    {
        return self::mac(self::OTP_FILE, 'otp|' . $identity);
    }

    /**
     * OTP file name stem for the legacy OTP controllers. Without a valid key the request fails closed
     * through the global error handler (generic message + reference), so no OTP is ever written to or
     * read from a name shared between identities.
     */
    public static function otpStem(string $identity): string
    {
        $n = self::otpName($identity);
        if ($n === null) {
            throw new \RuntimeException('OTP unavailable: the application key ($app_secret) is not configured');
        }
        return $n;
    }
}
